-- Distrito's Zonario source, bound by slug because the project id is generated per environment.
insert into public.development_project_sources
  (id, project_id, source_url, source_type, scope, http_status, checked_at, source_updated_at,
   fact_status, confidence, notes, observed_facts, created_at, updated_at)
select 'eeb6bdae-862f-4494-b900-a957120ff21a'::uuid, p.id, 'https://www.zonario.co/proyecto/medellin/distrito-33', 'aggregator', 'project', 200,
       '2026-10-06T13:54:16.213368+00:00'::timestamptz, null,
       'confirmed', 'B', 'Direct Zonario project page checked 2026-10-06. Facts describe a development for sale; they do not establish rental availability or owner/agent control.', '{"vis":false,"address":"Calle 33 #74B-202, Laureles - Estadio, Medellín, Antioquia, Colombia","estrato":4,"latitude":6.239272,"developer":"Arco Construcciones E Ingenieria","longitude":-75.5922253,"area_max_m2":53,"area_min_m2":26,"bedrooms_max":1,"bedrooms_min":1,"price_to_cop":572400000,"price_from_cop":291500000,"project_status":"Sobre planos"}'::jsonb,
       '2026-10-06T13:54:16.213368+00:00'::timestamptz, '2026-10-06T13:54:16.213368+00:00'::timestamptz
from public.development_projects p where p.slug = 'distrito-33'
on conflict (id) do nothing;

-- Distrito's project-row enrichment (price/address/coords) came from the Zonario page and was
-- production-only too; derive it from the captured source facts so the row is reproducible.
update public.development_projects p
set price_from_cents = ((s.observed_facts ->> 'price_from_cop')::numeric * 100)::bigint,
    price_to_cents = ((s.observed_facts ->> 'price_to_cop')::numeric * 100)::bigint,
    address = s.observed_facts ->> 'address',
    latitude = (s.observed_facts ->> 'latitude')::numeric,
    longitude = (s.observed_facts ->> 'longitude')::numeric,
    verified_at = s.checked_at
from public.development_project_sources s
where p.slug = 'distrito-33'
  and s.project_id = p.id
  and s.observed_facts ? 'price_from_cop';

update public.development_projects p
set primary_source_id = v.primary_source_id,
    source_url = s.source_url,
    verified_at = s.checked_at
from (values
  ('los-cambulos'::text, '3413ed04-e105-42c8-b22a-846dcbaf9416'::uuid),
  ('olium-park'::text, 'f456b26e-ef26-4937-87c7-6b6b4ebbc13e'::uuid),
  ('reserva-serrat-selva'::text, '2b8a36df-3dcf-4f72-98d3-0a09b5b89d68'::uuid),
  ('faroverde'::text, '6f200483-56a5-4224-a62a-2d03a9644e72'::uuid),
  ('cittadel'::text, 'aa8f1703-622b-4a5f-a959-cec69c590042'::uuid),
  ('crista'::text, 'a9567e50-36e2-4798-9665-cd0f48ce9393'::uuid)
) as v(slug, primary_source_id)
join public.development_project_sources s on s.id = v.primary_source_id
where p.slug = v.slug;
